            uses={r:get(route+'-USE-'+r) for r in ROLES}
            row.update(J=all_known([conf.get('V'),conf.get('C')]+[u.get(k) for u in uses.values() for k in ('L','H','Z')]),
                U_target=all_known([uses[p['target']].get(k) for k in ('L','Z_local')]),
